+    private void onQualityClicked() {
+        qualityPopupMenu.show();
+        isSomePopupMenuVisible = true;
+
+        final VideoStream videoStream = player.getSelectedVideoStream();
+        if (videoStream != null) {
+            //noinspection SetTextI18n
